-- FAANG mastery curriculum expansion (applied to production Supabase on 2026-11-11).
-- Idempotent reconciliation: preserves existing topic/problem IDs and upserts by stable topic/order identity.
begin;

-- New topic shells. Explicit IDs are stable curriculum identities.
insert into public.topics
(id,display_number,show_in_sidebar,nav_section,nav_label,nav_tier_dot_color,title,tier_code,tier_label,type_label,summary_meta,topbar_meta,body_html,is_free)
values
(44,'44',true,'Advanced Techniques','Bit Manipulation','#da7101','Bit Manipulation & Bitwise Algorithms','T4','Advanced','Bitwise Algorithms','16 problems · XOR invariants, bit counting, range operations, Gray code, SOS DP and XOR basis','Advanced Techniques · Bitwise Algorithms','',false),
(45,'45',true,'Advanced Techniques','Meet in the Middle','#da7101','Meet-in-the-Middle & Subset Optimisation','T4','Advanced','Subset Enumeration · Search · Optimisation','5 problems · split exponential search, subset counting, closest sum, modular residues and multidimensional states','Advanced Techniques · Meet-in-the-Middle','',false),
(46,'46',true,'Advanced Techniques','Advanced Strings','#da7101','Advanced String Algorithms','T4','Advanced','String Indexing · Hashing · Palindromes','7 problems · rolling hash, suffix arrays, LCP, suffix automata and Manacher','Advanced Techniques · Advanced Strings','',false)
on conflict (id) do update set
 display_number=excluded.display_number,show_in_sidebar=excluded.show_in_sidebar,nav_section=excluded.nav_section,
 nav_label=excluded.nav_label,nav_tier_dot_color=excluded.nav_tier_dot_color,title=excluded.title,
 tier_code=excluded.tier_code,tier_label=excluded.tier_label,type_label=excluded.type_label,
 summary_meta=excluded.summary_meta,topbar_meta=excluded.topbar_meta,is_free=excluded.is_free;

insert into public.topic_content
(topic_id,why_it_matters,core_idea,sub_variants,pattern_triggers,coverage_problems,red_flags)
values
(44,
'Bitwise reasoning represents sets, parity, independent binary decisions and algebra over GF(2). The aim is to derive the invariant, not memorise tricks.',
'Treat an integer as a fixed-width bit vector and state width and signedness. AND intersects set bits; OR unions them; XOR is addition over GF(2). Masks encode subsets. For interval operations identify invariant leading bits; for subarray OR maintain the small frontier of distinct suffix states; for XOR optimisation use Gaussian elimination over GF(2).',
'["Bitwise primitives and population count","XOR cancellation and parity invariants","Per-bit frequency modulo k","Distinguishing-bit partition","Common-prefix range AND","Carry propagation","Greedy bit construction","Gray code and inverse Gray code","Distinct bitwise-OR frontier","SOS DP / subset zeta transform","XOR linear basis over GF(2)","Range maximum-XOR queries with segment tree of bases"]'::jsonb,
'[{"trigger":"Pairs cancel except one","breaks_when":"Multiplicity assumptions differ","sub_variant":"XOR cancellation"},{"trigger":"One value appears once and others k times","breaks_when":"k varies per value","sub_variant":"Per-bit count modulo k"},{"trigger":"Find two unique values among pairs","breaks_when":"XOR of unique values is zero","sub_variant":"Partition by a distinguishing set bit"},{"trigger":"AND every number in an interval","breaks_when":"Machine-width semantics are unspecified","sub_variant":"Common leading binary prefix"},{"trigger":"Add without arithmetic addition","breaks_when":"Fixed-width overflow model is unspecified","sub_variant":"XOR partial sum and shifted AND carry"},{"trigger":"Count distinct subarray OR values","breaks_when":"Operator does not monotonically accumulate bits","sub_variant":"Distinct suffix-state frontier"},{"trigger":"Count tuples with bitwise AND zero for small bit width","breaks_when":"2^B is infeasible","sub_variant":"SOS DP / subset zeta transform"},{"trigger":"Maximise XOR over a subset or range","breaks_when":"Constraints are not captured by linear span","sub_variant":"Gaussian elimination over GF(2)"}]'::jsonb,
'["LC 136 Single Number","LC 137 Single Number II","LC 260 Single Number III","LC 338 Counting Bits","LC 190 Reverse Bits","LC 201 Bitwise AND of Numbers Range","LC 371 Sum of Two Integers","LC 1318 Minimum Flips","LC 2429 Minimize XOR","LC 1829 Maximum XOR for Each Query","LC 898 Bitwise ORs of Subarrays","LC 89 Gray Code","LC 1611 Minimum One Bit Operations","LC 982 Triples with Bitwise AND Equal To Zero","Custom XOR linear basis","CF 1100F Ivan and Burgers"]'::jsonb,
'["State what each bit means and fix the width and signedness.","In Java use 1L << bit for long masks and >>> for logical right shift.","A bit trick needs an invariant proof.","SOS DP requires feasible 2^B memory and time.","An XOR basis spans a vector space over GF(2), not a sorted set."]'::jsonb),
(45,
'Meet-in-the-middle reduces an infeasible 2^n search to two roughly 2^(n/2) enumerations for n around 30–45. It is a distinct technique from global bitmask DP: split decisions, enumerate sufficient summaries, and join them.',
'Partition decisions into halves A and B. Enumerate 2^(n/2) summaries per half, preserving every dimension needed to combine solutions (sum, residue, cardinality, resource count). Sort or index one side, then query compatible partners. Prove every full solution decomposes into one pair of half-solutions and preserve duplicate multiplicity.',
'["Subset-sum counting and complement lookup","Closest subset sum via lower_bound","Maximum subset sum modulo m","Cardinality-aware meet-in-the-middle","Multi-choice states with resource budget","Dominance pruning and deduplication","Choosing between MITM, bitmask DP and knapsack"]'::jsonb,
'[{"trigger":"n too large for 2^n but small enough for 2^(n/2)","breaks_when":"Even half enumeration is infeasible","sub_variant":"Split decisions and join summaries"},{"trigger":"Count target-sum subsets for n around 40","breaks_when":"Target is small enough for pseudo-polynomial DP","sub_variant":"Half sums and complement counting"},{"trigger":"Find subset sum closest to target","breaks_when":"A polynomial greedy or monotone structure exists","sub_variant":"Sorted half sums and nearest-complement search"},{"trigger":"Maximise subset sum modulo m","breaks_when":"Modulus small enough for direct DP","sub_variant":"Sorted half residues and wrap-around search"},{"trigger":"Validity depends on sum and cardinality/resource count","breaks_when":"Extra dimension is small enough for direct DP","sub_variant":"Multi-dimensional half-state summaries"}]'::jsonb,
'["CSES 1628 Meet in the Middle","LC 1755 Closest Subsequence Sum","CF 888E Maximum Subsequence","LC 805 Split Array With Same Average","CF 525E Anya and Cubes"]'::jsonb,
'["Compare 2^(n/2) time and memory against DP before choosing MITM.","Retain every dimension needed by the global constraint.","Preserve multiplicity when counting subsets with equal sums.","Handle empty/full subsets explicitly.","For modulo objectives account for wrap-around."]'::jsonb),
(46,
'KMP and Aho–Corasick cover prefix-based matching and multiple-pattern automata, but not suffix indexing, substring ordering, distinct-substring counting or linear-time palindrome radii.',
'Choose a structure from the query shape. Rolling hash fingerprints substrings but requires collision awareness. Suffix arrays sort suffixes; LCP quantifies overlap. Suffix automata merge substrings with equal end-position behaviour. Manacher computes odd/even palindrome radii in linear time. Use deterministic structures or verify hash candidates when correctness must be absolute.',
'["Polynomial rolling hash and prefix hashes","Cross-string matching with binary search on length","Suffix array and pattern search","LCP and distinct-substring counting","K-th lexicographic substring queries","Suffix automaton and end-position equivalence","Cyclic pattern matching","Manacher odd/even palindrome radii"]'::jsonb,
'[{"trigger":"Many substring equality checks or common-substring search","breaks_when":"Hash collisions cannot be tolerated without verification","sub_variant":"Rolling hash with double hashing or candidate verification"},{"trigger":"Lexicographic suffix order or substring-order queries","breaks_when":"Only one short pattern search is required","sub_variant":"Suffix array plus LCP"},{"trigger":"Count distinct substrings or find k-th substring","breaks_when":"Only fixed-pattern matching is needed","sub_variant":"Suffix-array contributions or suffix-automaton intervals"},{"trigger":"Match cyclic shifts or count many substring occurrences","breaks_when":"A fixed small pattern set suits KMP/Aho–Corasick","sub_variant":"Suffix automaton and suffix links"},{"trigger":"All palindrome radii or longest palindrome in linear time","breaks_when":"Only a few short centers are queried","sub_variant":"Manacher odd/even radii"}]'::jsonb,
'["LC 1923 Longest Common Subpath","CSES 2102 Finding Patterns","CSES 2103 Substring Order I","CSES 2104 Substring Order II","CF 235C Cyclical Quest","CF 271D Good Substrings","Custom Manacher"]'::jsonb,
'["Rolling hash is probabilistic unless collisions are verified or otherwise controlled.","Define the LCP indexing convention explicitly.","Distinct-substring contributions subtract overlap with the adjacent suffix.","A suffix-automaton state contributes len(v)-len(link(v)) substrings before additional constraints.","Manacher needs separate odd and even radii."]'::jsonb)
on conflict (topic_id) do nothing;

-- Extend existing topic teaching content without duplicating entries on a replay.
update public.topic_content set
 sub_variants=sub_variants || '["Deterministic Miller–Rabin for 64-bit primality","Pollard Rho factorisation with Miller–Rabin","Möbius inversion for gcd constraints and coprime-pair counting"]'::jsonb,
 core_idea=core_idea || E'\n\nLarge-integer number theory: for isolated values near 10^18 use deterministic Miller–Rabin with a proven witness set and overflow-safe modular multiplication. Pollard Rho finds non-trivial factors using pseudorandom iteration and gcd, combined recursively with primality testing. Möbius inversion converts gcd constraints into divisor sums weighted by μ(d).',
 why_it_matters=why_it_matters || E'\n\nThe advanced range now covers isolated huge integers, factorisation of large composites, and divisor-sum inversion beyond bounded sieve precomputation.'
where topic_id=10 and not (sub_variants @> '["Deterministic Miller–Rabin for 64-bit primality"]'::jsonb);

update public.topic_content set
 sub_variants=sub_variants || '["Minimum vertex cover from maximum matching via alternating reachability (König)","Hall-deficient set construction as a certificate","Weighted bipartite assignment via Hungarian primal-dual algorithm"]'::jsonb,
 core_idea=core_idea || E'\n\nMatching duality: König''s theorem equates maximum matching and minimum vertex-cover size in bipartite graphs. Alternating reachability constructs a minimum cover and a Hall-deficient witness when left-perfect matching fails. Weighted assignment uses Hungarian primal-dual potentials and augmenting paths.',
 why_it_matters=why_it_matters || E'\n\nThe matching path now continues beyond cardinality matching to dual certificates, Hall obstructions and minimum-cost assignment.'
where topic_id=23 and not (sub_variants @> '["Minimum vertex cover from maximum matching via alternating reachability (König)"]'::jsonb);

update public.topic_content set
 sub_variants=sub_variants || '["Dinic maximum flow with residual edges, level graph and current-arc optimisation","Minimum s-t cut extraction from residual reachability","Integral maximum flow and edge-disjoint path decomposition","Vertex-disjoint paths via node splitting and vertex capacities"]'::jsonb,
 core_idea=core_idea || E'\n\nFlow networks: encode resource limits as capacities and enforce conservation. Residual edges represent unused capacity and the ability to undo prior routing. Dinic builds BFS level graphs and sends blocking flow with DFS/current-arc pointers. When no augmenting path remains, residual reachability yields a minimum cut. Integral capacities enable edge-disjoint path decomposition; vertex-disjoint paths use node splitting.',
 why_it_matters=why_it_matters || E'\n\nThe required graph curriculum now includes complete max-flow modelling, min-cut recovery and disjoint-path extraction.'
where topic_id=29 and not (sub_variants @> '["Dinic maximum flow with residual edges, level graph and current-arc optimisation"]'::jsonb);

-- Required problem additions. Conflict handling preserves existing row IDs and progress references.
insert into public.problems
(topic_id,order_num,layer,lc_number,lc_url,title,difficulty,is_premium,sub_variant,key_insight,is_required,curriculum_role,curriculum_path,curriculum_path_order,path_problem_order)
values
(10,19,'Hard',null,null,'Primality Queries up to 10^18 — Deterministic Miller–Rabin','Hard',false,'Deterministic 64-bit primality testing','Write n−1=d·2^s and test modular powers for each witness. A proven witness set gives a deterministic guarantee only for its stated integer domain; use overflow-safe modular multiplication and state the supported bound.',true,'core_pattern','Primality testing and large-integer factorisation',5,1),
(10,20,'Hard',null,null,'Factorise 64-bit Integers — Pollard Rho + Miller–Rabin','Hard',false,'Large semiprime factorisation','Use Miller–Rabin to detect prime residuals; otherwise Pollard Rho iterates x=f(x), y=f(f(y)) and computes gcd(|x−y|,n). Restart on trivial factors/stalls, recursively factor both parts, and explain randomised expected behaviour and overflow-safe modular arithmetic.',true,'combination','Primality testing and large-integer factorisation',5,2),
(10,21,'Hard',null,null,'Count Coprime Pairs up to N — Möbius Inversion','Hard',false,'Möbius inversion over common divisors','Use [gcd(a,b)=1]=Σ(d|a,d|b) μ(d). Ordered pairs in [1,N]^2 give Σ μ(d) floor(N/d)^2; adjust for unordered/distinct semantics. Derive from Σ(d|g)μ(d)=1 iff g=1.',true,'combination','Primality testing and large-integer factorisation',5,3),
(23,16,'Hard',null,null,'Minimum Vertex Cover in a Bipartite Graph','Hard',false,'König duality and alternating reachability','From all unmatched left vertices traverse unmatched L→R and matched R→L edges. If reached sets are ZL,ZR, then (L\ZL)∪ZR is a minimum vertex cover. Prove every edge is covered and its size equals maximum matching.',true,'combination','Matching duality, certificates and weighted assignment',4,1),
(23,17,'Hard',null,null,'Hall''s Theorem — Construct a Deficient Set','Hard',false,'Hall obstruction certificate','If maximum matching leaves a left vertex unmatched, alternating reachability from all unmatched left vertices yields S and N(S) with |S|>|N(S)|. This concrete witness proves no matching can saturate the left partition.',true,'combination','Matching duality, certificates and weighted assignment',4,2),
(23,18,'Hard',null,null,'Minimum-Cost Perfect Assignment — Hungarian Algorithm','Hard',false,'Weighted bipartite assignment','Maintain row/column dual potentials and reduced costs. Augment through zero reduced-cost edges; when blocked, update potentials by minimum slack. Prove dual feasibility and optimality; handle negative costs and rectangular assignment.',true,'combination','Matching duality, certificates and weighted assignment',4,3),
(29,21,'Hard','CSES 1694','https://cses.fi/problemset/task/1694','Download Speed','Hard',false,'Dinic maximum flow','Build residual edges with reverse-edge indices. BFS creates a level graph; DFS sends blocking flow using current-arc pointers. Repeat until sink is unreachable. Use long capacities and verify conservation.',true,'core_pattern','Flow networks, cuts and disjoint paths',5,1),
(29,22,'Hard','CSES 1695','https://cses.fi/problemset/task/1695','Police Chase','Hard',false,'Minimum s-t cut extraction','Run max flow, then traverse positive-capacity residual edges from source. The reached set and complement form a minimum cut; recover original undirected crossing edges and preserve original edge identity.',true,'variant','Flow networks, cuts and disjoint paths',5,2),
(29,23,'Hard','CSES 1711','https://cses.fi/problemset/task/1711','Distinct Routes','Hard',false,'Edge-disjoint path decomposition','Give directed edges capacity 1. Integral max flow equals maximum edge-disjoint route count. Decompose positive original flow into source-to-sink paths; do not mistake residual capacity for final flow.',true,'combination','Flow networks, cuts and disjoint paths',5,3),
(29,24,'Combo',null,null,'Vertex-Disjoint Routes via Node Splitting (Custom)','Hard',false,'Vertex capacities by node splitting','Replace each vertex v by v_in→v_out with the vertex capacity; redirect incoming/outgoing edges accordingly. Run max flow and reconstruct paths, handling source/sink capacity semantics explicitly.',true,'combination','Flow networks, cuts and disjoint paths',5,4),
(44,1,'Foundation','136','https://leetcode.com/problems/single-number/','Single Number','Easy',false,'XOR cancellation invariant','XOR is associative and commutative; x xor x=0 and x xor 0=x. Paired values cancel, leaving the unique value under the stated multiplicity assumption.',true,'core_pattern','Bitwise primitives and XOR invariants',1,1),
(44,2,'Variants','137','https://leetcode.com/problems/single-number-ii/','Single Number II','Med',false,'Per-bit frequency modulo three','Count each bit modulo 3; the remaining bit vector is the unique value. Derive the finite-state counter and handle signed two''s-complement reconstruction.',true,'variant','Bitwise primitives and XOR invariants',1,2),
(44,3,'Variants','260','https://leetcode.com/problems/single-number-iii/','Single Number III','Med',false,'XOR partition by a distinguishing bit','XOR all values to obtain a xor b; isolate a set bit such as diff & -diff and XOR each partition. Paired values stay in one group.',true,'variant','Bitwise primitives and XOR invariants',1,3),
(44,4,'Foundation','338','https://leetcode.com/problems/counting-bits/','Counting Bits','Easy',false,'Population-count recurrence','dp[i]=dp[i&(i−1)]+1 because clearing the lowest set bit removes exactly one 1. Compare with the right-shift recurrence.',true,'core_pattern','Bitwise primitives and XOR invariants',1,4),
(44,5,'Variants','190','https://leetcode.com/problems/reverse-bits/','Reverse Bits','Easy',false,'Fixed-width bit extraction and reconstruction','Process exactly 32 bits, shifting the result and appending the lowest input bit. In Java distinguish >> from >>> and preserve leading zeroes.',true,'variant','Bitwise primitives and XOR invariants',1,5),
(44,6,'Variants','201','https://leetcode.com/problems/bitwise-and-of-numbers-range/','Bitwise AND of Numbers Range','Med',false,'Common-prefix interval invariant','The interval AND retains only the common leading binary prefix. Shift both bounds until equal, then restore the prefix.',true,'core_pattern','Range operations and bitwise construction',2,1),
(44,7,'Variants','371','https://leetcode.com/problems/sum-of-two-integers/','Sum of Two Integers','Med',false,'Carry propagation with XOR and shifted AND','XOR gives partial sum without carry; (a&b)<<1 gives carry. Repeat until carry is zero under fixed-width integer semantics.',true,'variant','Bitwise primitives and XOR invariants',1,6),
(44,8,'Variants','1318','https://leetcode.com/problems/minimum-flips-to-make-a-or-b-equal-to-c/','Minimum Flips to Make a OR b Equal to c','Med',false,'Per-bit constraint satisfaction','If c bit is 1, at least one input bit must be 1; if c bit is 0, clear every set bit in both inputs. The latter may require two flips.',true,'variant','Bitwise primitives and XOR invariants',1,7),
(44,9,'Variants','2429','https://leetcode.com/problems/minimize-xor/','Minimize XOR','Med',false,'Greedy bit placement under fixed popcount','Preserve high set-bit positions of num1 first, then fill the lowest zero positions until the result has popcount(num2). Prove by the most significant differing bit.',true,'combination','Range operations and bitwise construction',2,2),
(44,10,'Variants','1829','https://leetcode.com/problems/maximum-xor-for-each-query/','Maximum XOR for Each Query','Med',false,'Prefix XOR and complement under width mask','Maximise prefixXor xor k by choosing k as the complement within the allowed bit width. Unbounded NOT is not the intended mask.',true,'variant','Range operations and bitwise construction',2,3),
(44,11,'Variants','898','https://leetcode.com/problems/bitwise-ors-of-subarrays/','Bitwise ORs of Subarrays','Med',false,'Distinct suffix-state frontier','For each x form {x} plus every previous OR-state combined with x. OR only changes 0→1, so each suffix chain changes at most B times.',true,'combination','Range operations and bitwise construction',2,4),
(44,12,'Variants','89','https://leetcode.com/problems/gray-code/','Gray Code','Med',false,'Gray-code encoding and inverse transform','Binary-reflected Gray code is g=i xor (i>>1); adjacent values differ in one bit. Derive inverse by prefix XOR.',true,'core_pattern','Gray code and bitwise state transitions',3,1),
(44,13,'Hard','1611','https://leetcode.com/problems/minimum-one-bit-operations-to-make-integers-zero/','Minimum One Bit Operations to Make Integers Zero','Hard',false,'Inverse Gray-code structure','The minimum operation count equals the inverse Gray-code value. Derive prefix-XOR decoding or the highest-set-bit recurrence from legal transitions.',true,'combination','Gray code and bitwise state transitions',3,2),
(44,14,'Hard','982','https://leetcode.com/problems/triples-with-bitwise-and-equal-to-zero/','Triples with Bitwise AND Equal To Zero','Hard',false,'SOS DP / subset zeta transform','Subset zeta counts array masks that are submasks of each mask. For pair (a,b), valid c are submasks of complement(a&b) within B bits. O(B·2^B+n²).',true,'combination','Subset transforms and XOR linear algebra',4,1),
(44,15,'Hard',null,null,'Maximum XOR of Any Subset — Build a Linear Basis','Hard',false,'Gaussian elimination over GF(2)','Insert values from high bit to low, reducing against existing pivots. The nonzero pivots span all subset XORs; greedily apply pivots to maximise the result.',true,'core_pattern','Subset transforms and XOR linear algebra',4,2),
(44,16,'Hard','CF 1100F','https://codeforces.com/problemset/problem/1100/F','Ivan and Burgers','Hard',false,'Range maximum-XOR queries with segment tree of linear bases','Each segment-tree node stores a basis spanning its interval. Merge child bases by inserting pivots; merge O(log n) nodes for a range and greedily maximise XOR.',true,'combination','Subset transforms and XOR linear algebra',4,3),
(45,1,'Hard','CSES 1628','https://cses.fi/problemset/task/1628','Meet in the Middle','Hard',false,'Count target-sum subsets by split enumeration','Enumerate half subset sums and count complementary pairs. Preserve multiplicity of equal sums; compare against pseudo-polynomial knapsack when target is small.',true,'core_pattern','Subset counting and exact-sum joins',1,1),
(45,2,'Hard','1755','https://leetcode.com/problems/closest-subsequence-sum/','Closest Subsequence Sum','Hard',false,'Sorted half-sums and nearest-complement search','Enumerate half sums, sort one side, and inspect lower_bound(goal−leftSum) and its predecessor. Use long arithmetic.',true,'variant','Subset counting and exact-sum joins',1,2),
(45,3,'Hard','CF 888E','https://codeforces.com/problemset/problem/888/E','Maximum Subsequence','Hard',false,'Maximum subset sum modulo m','Enumerate half residues modulo m. For each left residue binary-search the best right residue below the wrap boundary; account for modular wrap-around.',true,'variant','Subset counting and exact-sum joins',1,3),
(45,4,'Hard','805','https://leetcode.com/problems/split-array-with-same-average/','Split Array With Same Average','Hard',false,'Meet-in-the-middle with sum and cardinality','A subset of size k and sum s has the full average iff n·s=k·total. Join (count,sum) states and exclude empty/full subsets.',true,'combination','Cardinality and multi-resource constraints',2,1),
(45,5,'Hard','CF 525E','https://codeforces.com/problemset/problem/525/E','Anya and Cubes','Hard',false,'Half-state enumeration with factorial budget','Each item is skipped, taken normally, or factorialised while consuming budget. Join (sum,factorialCount) summaries; preserve assignment multiplicity and guard overflow.',true,'combination','Cardinality and multi-resource constraints',2,2),
(46,1,'Hard','1923','https://leetcode.com/problems/longest-common-subpath/','Longest Common Subpath','Hard',false,'Binary search length and intersect rolling hashes','Length L is feasible iff a length-L substring occurs in every path. Intersect hash sets for all paths and binary-search L; use double hash or verification.',true,'core_pattern','Rolling hash and cross-string matching',1,1),
(46,2,'Hard','CSES 2102','https://cses.fi/problemset/task/2102','Finding Patterns','Hard',false,'Suffix array pattern interval search','Suffixes prefixed by a pattern form a contiguous lexicographic interval. Binary-search lower/upper bounds with careful prefix comparison.',true,'variant','Suffix arrays and LCP-based indexing',2,1),
(46,3,'Hard','CSES 2103','https://cses.fi/problemset/task/2103','Substring Order I','Hard',false,'K-th distinct substring via suffix array and LCP','Suffix i contributes n−SA[i]−LCP[i] new substrings beyond its predecessor. Subtract contributions from k and construct the target prefix.',true,'combination','Suffix arrays and LCP-based indexing',2,2),
(46,4,'Hard','CSES 2104','https://cses.fi/problemset/task/2104','Substring Order II','Hard',false,'K-th substring counting repeated occurrences','Count all non-empty prefixes of suffixes in suffix-array order, including duplicate substring occurrences; contrast with distinct-substring contribution in Order I.',true,'variant','Suffix arrays and LCP-based indexing',2,3),
(46,5,'Hard','CF 235C','https://codeforces.com/problemset/problem/235/C','Cyclical Quest','Hard',false,'Suffix automaton for cyclic-shift matching','Scan s+s while maintaining automaton state and matched length, capped at |s|. Use suffix links and occurrence aggregation to count valid rotations without duplicates.',true,'combination','Suffix automata and cyclic matching',3,1),
(46,6,'Hard','CF 271D','https://codeforces.com/problemset/problem/271/D','Good Substrings','Hard',false,'Distinct valid substrings with suffix automaton','Use a two-pointer bound on valid length per end position, propagate maximum valid length to suffix-automaton states through suffix links, and count max(0,min(len[v],valid[v])−len(link[v])).',true,'combination','Suffix automata and cyclic matching',3,2),
(46,7,'Hard',null,null,'Manacher — Compute Every Palindrome Radius in O(n)','Hard',false,'Odd/even palindrome radii','Maintain rightmost palindrome [l,r], seed radius from its mirror, expand, and update [l,r]. Run separate odd and even passes; right boundary advances monotonically.',true,'core_pattern','Palindrome radii and linear-time structure',4,1)
on conflict (topic_id,order_num) do nothing;

-- Correct the Codeforces problem identity: 1100F is Ivan and Burgers.
update public.problems set title='Ivan and Burgers', key_insight='Answer range maximum-XOR queries using a segment tree of mergeable linear bases. Each node stores a basis spanning its interval; merge child bases by inserting pivots, then merge O(log n) nodes for a query and greedily maximise XOR.' where topic_id=44 and order_num=16;


-- Add decision triggers for the newly covered number-theory, matching and flow patterns.
update public.topic_content set pattern_triggers=pattern_triggers || '[
 {"trigger":"Primality queries involve values too large for a sieve and trial division","breaks_when":"Dense bounded range where a sieve is faster","sub_variant":"Deterministic Miller–Rabin with a proven witness set"},
 {"trigger":"Factor a large 64-bit composite or semiprime","breaks_when":"Small values or dense bounded domain","sub_variant":"Miller–Rabin plus Pollard Rho"}
]'::jsonb
where topic_id=10 and not (pattern_triggers @> '[{"trigger":"Primality queries involve values too large for a sieve and trial division"}]'::jsonb);

update public.topic_content set pattern_triggers=pattern_triggers || '[
 {"trigger":"Find the smallest set of vertices touching every edge in a bipartite graph","breaks_when":"The graph is not bipartite","sub_variant":"König minimum vertex cover via alternating reachability"},
 {"trigger":"Prove no matching can saturate the left partition and return a witness subset","breaks_when":"A left-perfect matching exists","sub_variant":"Hall-deficient set S with |N(S)| < |S|"},
 {"trigger":"Assign workers to distinct tasks while minimising total cost","breaks_when":"Only cardinality matching is required","sub_variant":"Hungarian primal-dual assignment"}
]'::jsonb
where topic_id=23 and not (pattern_triggers @> '[{"trigger":"Find the smallest set of vertices touching every edge in a bipartite graph"}]'::jsonb);

update public.topic_content set pattern_triggers=pattern_triggers || '[
 {"trigger":"Maximise throughput from one source to one sink under edge capacities","breaks_when":"Negative capacities or non-network constraints","sub_variant":"Dinic residual network and blocking flow"},
 {"trigger":"Find the smallest edge set whose removal disconnects source and sink","breaks_when":"Additional cut constraints alter the problem","sub_variant":"Max-flow/min-cut duality and residual reachability"},
 {"trigger":"Find maximum edge-disjoint source-to-sink routes","breaks_when":"Routes may share edges with capacity greater than one","sub_variant":"Unit-capacity max flow and integral path decomposition"},
 {"trigger":"Find vertex-disjoint routes","breaks_when":"Only edge-disjointness is required","sub_variant":"Node splitting and vertex capacities"}
]'::jsonb
where topic_id=29 and not (pattern_triggers @> '[{"trigger":"Maximise throughput from one source to one sink under edge capacities"}]'::jsonb);

-- Keep generated topic IDs safe for the next default insert after explicit IDs 44–46.
do $$
declare seq_name text;
begin
  seq_name := pg_get_serial_sequence('public.topics','id');
  if seq_name is not null then
    perform setval(seq_name, greatest((select coalesce(max(id),1) from public.topics), 1), true);
  end if;
end $$;

commit;

-- Post-migration invariants:
-- 46 topic rows; 44 sidebar-visible topics; 1,349 problem rows; 957 required placements.
-- All required problems have curriculum_path + positive path order and unique path positions.
